# Verify hypothesis: output is dominant non-background color in 3x3 block
def get_output_hypothesis(grid, r, c):
    """Returns what the output should be based on dominant non-bg color"""
    bg_colors = {0, 5}
    color_counts = {}
    for row_idx in range(3):
        row = grid[r*3 + row_idx][c*3:(c+1)*3]
        for col_idx in range(3):
            val = row[col_idx]
            if val not in bg_colors:
                color_counts[val] = color_counts.get(val, 0) + 1

    if not color_counts:
        return 0

    # Return most frequent non-bg color
    max_count = max(color_counts.values())
    candidates = [k for k, v in color_counts.items() if v == max_count]

    if len(candidates) > 1:
        # Tie - need tiebreaker. Let's try smallest index?
        candidates.sort()
        return min(candidates)
    return candidates[0]

print("Verifying hypothesis for all 6x6 blocks:")
all_match = True
for i in range(6):
    for j in range(6):
        expected = get_output_hypothesis(demo_input, i, j)
        actual = demo_output[i][j]
        match = "✓" if expected == actual else "✗"
        if expected != actual:
            all_match = False
        print(f"Block ({i},{j}): expected={expected}, actual={actual} {match}")

print(f"\nAll blocks match: {all_match}")
